import sys

def step(grid, H, W):
    out = [['.'] * W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            n = 0
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == '#':
                        n += 1
            alive = grid[r][c] == '#'
            if alive and n in (2, 3):
                out[r][c] = '#'
            elif not alive and n == 3:
                out[r][c] = '#'
    return out

def main():
    data = sys.stdin.read().split('\n')
    H, W, k = map(int, data[0].split())
    grid = [list(data[1 + i]) for i in range(H)]
    for _ in range(k):
        grid = step(grid, H, W)
    sys.stdout.write('\n'.join(''.join(row) for row in grid))

main()
